  "inlineSchema": "// Database schema. Source-of-truth for both seeded scrape data and user-created listings.\n//\n// SWAP NOTE: when teammate's Postgres comes online, change `provider = \"sqlite\"` to\n// `provider = \"postgresql\"` and re-run `prisma migrate dev`. Field types stay the same.\n// The `images` field becomes a real `String[]` on Postgres (currently pipe-joined String).\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = env(\"DATABASE_URL\")\n}\n\nmodel Listing {\n  id Int @id @default(autoincrement())\n\n  // Source / identity\n  reference String?\n  url       String?\n  source    String?\n  agence    String?\n\n  // Address & geo\n  adresse      String?\n  gouvernerat  String?\n  delegation   String?\n  ville        String?\n  localite     String?\n  codep        String?\n  latitude     Float?\n  longitude    Float?\n  geoPrecision String? @map(\"geo_precision\")\n\n  // Listing meta\n  type           String?\n  contrat        String?\n  prix           Float?\n  prixOriginal   Float?  @map(\"prix_original\")\n  prixM2         Float?  @map(\"prix_m2\")\n  prixQ75Contrat Float?  @map(\"prix_q75_contrat\")\n\n  // Physical\n  surface           Float?\n  surfaceOriginal   Float? @map(\"surface_original\")\n  superficieTerrain Float? @map(\"superficie_terrain\")\n  pieces            Int?\n  piecesOriginal    Int?   @map(\"pieces_original\")\n  etage             Int?\n  etageOriginal     Int?   @map(\"etage_original\")\n  anneeConstr       Int?   @map(\"annee_constr\")\n\n  // Boolean amenities\n  hasAscenseur     Boolean? @map(\"has_ascenseur\")\n  hasBalcon        Boolean? @map(\"has_balcon\")\n  hasChaffage      Boolean? @map(\"has_chaffage\")\n  hasClimatisation Boolean? @map(\"has_climatisation\")\n  hasGarage        Boolean? @map(\"has_garage\")\n  hasGardien       Boolean? @map(\"has_gardien\")\n  hasJardin        Boolean? @map(\"has_jardin\")\n  hasParking       Boolean? @map(\"has_parking\")\n  hasPiscine       Boolean? @map(\"has_piscine\")\n  hasTerrasse      Boolean? @map(\"has_terrasse\")\n\n  // Other amenities (text)\n  cuisine                String?\n  salleDeBain            String? @map(\"salle_de_bain\")\n  chauffage              String?\n  climatisation          String?\n  installationsSportives String? @map(\"installations_sportives\")\n\n  // POI proximity counts\n  bus        Int?\n  railway    Int?\n  ecole      Int?\n  hopital    Int?\n  pharmacie  Int?\n  magasin    Int?\n  marche     Int?\n  restaurant Int?\n\n  // Standing / quality\n  standing        String?\n  hautStanding    Boolean? @map(\"haut_standing\")\n  bonEntourage    Boolean? @map(\"bon_entourage\")\n  bonEntourageLlm String?  @map(\"bon_entourage_llm\")\n\n  // Contact\n  tel String?\n\n  // Description / search text\n  titre            String?\n  description      String?\n  descClean        String? @map(\"desc_clean\")\n  caracBlock       String? @map(\"carac_block\")\n  caracteristiques String?\n  contratCarac     String? @map(\"contrat_carac\")\n  surfaceCarac     String? @map(\"surface_carac\")\n  codePostalCarac  String? @map(\"code_postal_carac\")\n\n  // Misc\n  fonds         String?\n  constructible String?\n  pleinAir      String? @map(\"plein_air\")\n  service       String?\n\n  // Images: ' | '-joined URLs (becomes String[] on Postgres)\n  images    String?\n  otherData String? @map(\"other_data\")\n\n  // Publication\n  datePublication String? @map(\"date_publication\")\n  pubYear         Int?    @map(\"pub_year\")\n  pubMonth        Int?    @map(\"pub_month\")\n\n  // App-side metadata\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n  isUserCreated Boolean  @default(false)\n\n  ownerId Int?\n  owner   User? @relation(fields: [ownerId], references: [id])\n\n  favorites Favorite[]\n\n  @@index([gouvernerat])\n  @@index([ville])\n  @@index([type])\n  @@index([contrat])\n  @@index([prix])\n  @@index([latitude, longitude])\n}\n\nmodel User {\n  id           Int     @id @default(autoincrement())\n  email        String  @unique\n  passwordHash String?\n  name         String?\n  role         String  @default(\"buyer\") // \"buyer\" | \"seller\" | \"admin\"\n\n  createdAt DateTime @default(now())\n\n  listings  Listing[]\n  favorites Favorite[]\n  sessions  Session[]\n  accounts  Account[]\n}\n\n// NextAuth.js v4 tables (credentials provider doesn't strictly require them\n// but keeping them lets us layer in OAuth providers later without a migration).\nmodel Account {\n  id                String  @id @default(cuid())\n  userId            Int\n  type              String\n  provider          String\n  providerAccountId String\n  refresh_token     String?\n  access_token      String?\n  expires_at        Int?\n  token_type        String?\n  scope             String?\n  id_token          String?\n  session_state     String?\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([provider, providerAccountId])\n}\n\nmodel Session {\n  id           String   @id @default(cuid())\n  sessionToken String   @unique\n  userId       Int\n  expires      DateTime\n  user         User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\nmodel VerificationToken {\n  identifier String\n  token      String   @unique\n  expires    DateTime\n\n  @@unique([identifier, token])\n}\n\nmodel Favorite {\n  id        Int      @id @default(autoincrement())\n  userId    Int\n  listingId Int\n  createdAt DateTime @default(now())\n\n  user    User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  listing Listing @relation(fields: [listingId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, listingId])\n}\n",
